 async function enterQueue(){if(matchId){fail("Finalize a conversa atual antes de procurar outra pessoa.");return;}if(pendingMatchId)return;setBusy(true);const r=await supabase.rpc("enter_queue",{p_state_code:queueStateFilter||null,p_city:queueCityFilter.trim()||null});setBusy(false);if(r.error){if(r.error.message.includes("DAILY_SEARCH_LIMIT_REACHED")){const quota=await supabase.rpc("get_queue_search_quota");const q=Array.isArray(quota.data)?quota.data[0]:quota.data;if(q)setQueueQuota({used:Number(q.searches_used||0),remaining:Number(q.searches_remaining??0),unlimited:Boolean(q.unlimited)});fail("Você usou as 20 buscas gratuitas de hoje. Amanhã suas buscas renovam. Se quiser continuar hoje, veja o pacote ilimitado na Loja CONNECT.");}else fail("Não foi possível entrar na fila: "+r.error.message);return;}const x=Array.isArray(r.data)?r.data[0]:r.data;if(!x||typeof x.matched!=="boolean"){fail("O servidor não confirmou sua entrada na fila. Tente novamente.");return;}if(x.matched){if(!x.match_id){fail("O servidor encontrou uma conexão, mas não retornou o identificador. Tente novamente.");return;}await loadPendingMatch(x.match_id);setChatMinimized(false);}else{setQueue("waiting");setNotice("Você entrou na fila. A busca continuará automaticamente enquanto aguarda.");}}
