 async function sendAttachment(file:File,kind:"image"|"audio"|"file",duration?:number){if(!matchId||!session?.user.id)return;if(file.size>50*1024*1024){fail("O arquivo deve ter no máximo 50 MB.");return;}setBusy(true);try{const safeName=file.name.replace(/[^a-zA-Z0-9._-]/g,"_").slice(-100)||"arquivo";const path=matchId+"/"+session.user.id+"/"+crypto.randomUUID()+"-"+safeName;const uploaded=await supabase.storage.from("connect-chat").upload(path,file,{upsert:false,contentType:file.type||"application/octet-stream",cacheControl:"3600"});if(uploaded.error)throw uploaded.error;const inserted=await supabase.from("messages").insert({match_id:matchId,sender_id:session.user.id,body:"",message_type:kind,attachment_path:path,attachment_name:file.name,attachment_mime:file.type||"application/octet-stream",attachment_size:file.size,duration_seconds:duration??null}).select("*").single();if(inserted.error)throw inserted.error;const message=await hydrateMessage(inserted.data);setMessages(old=>old.some(x=>x.id===message.id)?old:[...old,message]);}catch(x){fail(x instanceof Error?x.message:"Não foi possível enviar o anexo.");}finally{setBusy(false);}}
 async function toggleRecording(){if(recording){recorderRef.current?.stop();setRecording(false);return;}try{if(!navigator.mediaDevices?.getUserMedia||typeof MediaRecorder==="undefined")throw new Error("Seu navegador não permite gravar áudio aqui.");const stream=await navigator.mediaDevices.getUserMedia({audio:true});const candidates=["audio/webm;codecs=opus","audio/mp4","audio/webm"];const mime=candidates.find(x=>MediaRecorder.isTypeSupported(x));const recorder=new MediaRecorder(stream,mime?{mimeType:mime}:undefined);audioChunksRef.current=[];recordingStartedRef.current=Date.now();recorder.ondataavailable=e=>{if(e.data.size)audioChunksRef.current.push(e.data);};recorder.onstop=()=>{stream.getTracks().forEach(t=>t.stop());const blob=new Blob(audioChunksRef.current,{type:recorder.mimeType||"audio/webm"});const ext=blob.type.includes("mp4")?"m4a":"webm";const file=new File([blob],"audio-"+Date.now()+"."+ext,{type:blob.type});const duration=Math.max(1,Math.round((Date.now()-recordingStartedRef.current)/1000));void sendAttachment(file,"audio",duration);};recorderRef.current=recorder;recorder.start();setRecording(true);}catch(x){fail(x instanceof Error?x.message:"Não foi possível iniciar a gravação.");setRecording(false);}}
